INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('b4a313f8-8cfe-4a0f-b344-4063160c95bb', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "07053c33-54e0-4c19-8409-4a9463b73197", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "eee01969-a1b0-44f5-82ae-4f2f3a187bed", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "735c5756-df40-40c9-81d6-dd4ff6a46b40", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "6fce4cfe-066b-4a9d-acb6-2e7ae41ddb66", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "056ca89e-40a7-4f18-966c-55438df1de73", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "24012820-9ab6-43c9-881b-145abfeae7f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bb91ae32-7c13-4396-83cc-b047f44e2ea7", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "841e9e0d-e693-4c82-bf4b-453d8850d6a9", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "b38c6567-f9f2-44da-9b26-640cf47239db", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "47679ada-3a4c-494e-88ff-c85795d8ec7b", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9a5faff6-2594-459b-8677-62c00808b421", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3a0cf30c-29e8-46ef-af13-d8f1913a70c4", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "368e6ade-b5e5-4fe8-99bd-431c28267944", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7a1f53a2-1378-4178-93ad-c79b2ade64ac", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "4c677417-6cb4-4856-ae08-febe29e7e3a0", "text": "Igaz", "isCorrect": true}, {"id": "a3c75960-14f0-435f-a161-4faae6fd0db4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('988c6218-be59-42fb-b781-c7e92c054e25', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "c6234965-7d90-4042-b6bf-ad42b261e84f", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "00e97b6f-3342-4d60-b0e2-648808d55a07", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "1f37b2cf-5009-489b-9e55-b2fa853fa576", "text": "A számok leírása", "isCorrect": false}, {"id": "5f9c9e80-348f-4d65-92fb-0e008db51428", "text": "A vonalzó használata", "isCorrect": false}, {"id": "0129535b-4b21-45d6-8bce-f14891b6a42c", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "0c394eec-6838-4277-9c9d-b0016473b9b1", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "f0080330-6993-4f73-bc54-649ef18998bf", "text": "Igaz", "isCorrect": true}, {"id": "2a504fff-7315-448b-a1e0-8864000aa458", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e684452d-0e41-4be3-af1c-ed6b75c263c0", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "da757e78-d02f-434f-a967-0d904a3fe292", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "f3d4dccb-caa1-4b67-a963-4eeac2d0e977", "text": "Igaz", "isCorrect": true}, {"id": "83964806-7e24-4a9d-adfb-5b78476ccbc6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f2271a37-904f-4246-8ce6-0dded16dc230", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ead232b2-19a5-4acf-b36a-285bcd4d9cfb", "text": "A dolgozatok áttekintése segít a hiányosságok pótl