('34daae4d-422d-46b8-9498-66396ce0a088', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d5bf1b0b-a51f-496a-9a71-976c98513130", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "d2292abc-4ed3-45bd-83e7-2aa052520d73", "text": "Számláló", "isCorrect": true}, {"id": "4a0fd112-7f1d-4ef0-96fb-d49d95a70509", "text": "Nevező", "isCorrect": false}, {"id": "a393f4ee-e422-4bc3-bff2-7731547218cc", "text": "Törtvonal", "isCorrect": false}, {"id": "1739e0a0-7943-4589-9ce6-8674f0b79b84", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "f376cf1e-cbb3-428e-a19b-c7bafa80caaf", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "12d5ba9e-a512-477c-bc28-e638823093f0", "text": "Nevező", "isCorrect": true}, {"id": "0911ff4d-dc33-4db2-ab97-4994a9069407", "text": "Számláló", "isCorrect": false}, {"id": "d11db117-56eb-44d0-acf0-e67720064ed8", "text": "Osztó", "isCorrect": false}, {"id": "63eae66a-35e5-4cd1-88af-818e2c38948c", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "593b9ed0-2eb5-431b-acd7-839828a7b42d", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "866230cd-2847-4186-a667-05e4af029c82", "text": "6/8", "isCorrect": true}, {"id": "0befd279-6064-4224-9ed4-c3abf1f88987", "text": "5/6", "isCorrect": false}, {"id": "0dd8b60b-b242-4781-86cb-bb5296348297", "text": "3/8", "isCorrect": false}, {"id": "6d44f184-82f9-4b96-b0c6-e25444365663", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "8bd2617c-4e9f-4e5f-a356-7dd9af591740", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "d5f92de6-5ab5-4873-b4b8-59ab88dd05b3", "text": "3/5", "isCorrect": true}, {"id": "64fcb4f9-dc88-4a9b-8520-61c38599657b", "text": "3/10", "isCorrect": false}, {"id": "1770d5d9-f134-4c01-b006-35dd989081d2", "text": "6/5", "isCorrect": false}, {"id": "161a28d9-fa73-425a-8f8c-948a79e935b0", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "b6d7e7dd-d3f9-4381-9398-1fa04f0daea6", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "72d11e4e-ab39-4f7b-870c-47a2063119a6", "text": "Igaz", "isCorrect": true}, {"id": "f09bf3a7-0e6e-4715-b794-d67bfc8cab19", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "77902f36-836e-437f-9037-cb9b43278f55", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "736ab72e-77ae-4b79-97a1-da10ed65f25c", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "390edb31-cfea-4ca7-8f28-18ab4c899373", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "4fc205b2-c48e-48d9-bafb-40520c7a8a49", "text": "2/6", "isCorrect": false}, {"id": "fad29572-14d7-4bb1-a002-8fdf999ef794", "text": "2/4", "isCorrect": false}, {"id": "d439c9be-5317-49da-9113-82fb5b56c5e9", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());